# Living hoofed mammals (odd- and even-toed; whales and dolphins are in cetaceans.py): every
# genus, with its best-known species and the others mentioned. Ranges are country-level outlines,
# so they are approximate, and for domesticated animals show the wild range. IUCN statuses are
# given only where well established.


def C(*names, **clip):
    return {'countries': list(names), **clip}


def part(country, lon0, lat0, lon1, lat1):
    return {'country': country, 'bbox': [lon0, lat0, lon1, lat1]}


